ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns mdm http://www.etb.com.co/Gateway/MDM_Data_Services_V2
---
soapenv#Envelope: {
    soapenv#Header:{},
    soapenv#Body:{
        mdm#Set_LogTransaccional:{
            mdm#WSRequestHeader:{
                mdm#system:{
                    mdm#name: "Mulesoft",
                    mdm#correlationId: payload.Identificador_Peticion,
                    mdm#processingServer: "Mulesoft"
                }
            },
            mdm#WSRequestBody: {
                mdm#Identificador_Peticion: payload.Identificador_Peticion,
                mdm#Tipo_Documento: payload.Tipo_Documento,
                mdm#Numero_Identificacion: payload.Numero_Identificacion,
                mdm#Numero_Conexion: payload.Numero_Conexion,
                mdm#Tipo_Transaccion: payload.Tipo_Transaccion,
                mdm#Fecha_Inicio: payload.Fecha_Inicio,
                mdm#Fecha_Fin: payload.Fecha_Fin,
                mdm#Estado_Transaccion: payload.Estado_Transaccion,
                mdm#Sistema_Origen: payload.Sistema_Origen,
                mdm#Atributos: {
                    mdm#Atributo: payload.Atributos map (value, index) -> {
                        mdm#name: value.name,
                        mdm#value: value.value
                    }
                }

            }
        }
    }
}
